{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 창고시설의 부설주차장 일반 설치기준에 따른 주차대수(시설면적 2,670㎡)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 별표 2에서 창고시설의 부설주차장 설치기준은 시설면적 267㎡당 1대이다. 시설면적 2,670㎡를 267㎡로 나누면 10대가 된다. 따라서 일반 설치기준에 따른 주차대수는 10대이다.",
          "b_ids": "주차장:별표2#행9"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 장애인전용주차구획 설치 대상 시설물에서 부설주차장 설치기준 주차대수가 10대 미만일 때 장애인전용구획 설치 예외 적용 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제25조 제1항 단서에 따르면 부설주차장의 설치기준에 따른 주차대수가 10대 미만인 경우에는 장애인전용주차구획을 설치하지 아니할 수 있다. 이 창고의 일반 설치기준에 따른 주차대수는 10대이므로 10대 미만에 해당하지 않아 해당 예외를 적용할 수 없다.",
          "b_ids": "주차장:제25조제1항단서, 주차장:별표2#행9"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
